questionvariables.text:
/* --- Random triangle --- */
xshift: rand([-8,-6,-4,-2]);
yshift: rand([0,2,4,6]);
pts: [
   [xshift, yshift],
   [xshift + rand([3,4,5]), yshift + rand([2,3,4])],
   [xshift + rand([2,3,4]), yshift]
];

/* Compute triangle vertical extent */
yvals: map(second, pts);
ymin: lmin(yvals);
ymax: lmax(yvals);

/* --- Random slope --- */
lt: rand(3); /* 0 = horizontal, 1 = positive, 2 = negative */
slope_list: [0, 1, -1];
m: slope_list[lt+1];

/* --- Choose c so the line stays away from the triangle --- */
if m=0 then
    c: rand([ymin-3, ymin-2, ymax+2, ymax+3])
else
    c: rand([-6,-5,-4,4,5,6])$

/* --- Define reflection function --- */
reflect_point(x0, y0, m, c) := block(
  [A, B, C, d, xp, yp],
  /* For line y = m*x + c, the normal form is A*x + B*y + C = 0 */
  A: m, B: -1, C: c,
  d: (A*x0 + B*y0 + C) / (A^2 + B^2),
  xp: x0 - 2*A*d,
  yp: y0 - 2*B*d,
  [xp, yp]
);

/* --- Reflect all points to get model answer --- */
pts_image: map(lambda([p], reflect_point(first(p), second(p), m, c)), pts);
ta1: pts_image;

questionnote.text:
[[jsxgraph]]
var board = JXG.JSXGraph.initBoard(divid, {
    boundingbox: [-10, 10, 10, -6],
    axis: true,
    showCopyright: false
});

// Load random variables from STACK
var pts = {#pts#};
var m = {#m#};
var c = {#c#};

// --- Draw reflection line: y = m*x + c ---
var reflLine = board.create('functiongraph', [
    function(x) { return m * x + c; },
    -10, 10
], {
    strokeColor: 'blue',
    dash: 2,
    strokeWidth: 2,
    name: 'Reflection line'
});

// --- Draw original triangle ---
var labels = ['A', 'B', 'C'];
var objPts = [];
for (var i=0; i<pts.length; i++){
    objPts.push(board.create('point', pts[i], {
        name: labels[i],
        fixed: true,
        size: 3,
        fillColor: '#1f77b4',
        label: {offset:[-10,10]}
    }));
}
var shape = board.create('polygon', objPts, {
    fillColor: '#9ecae1', borders:{strokeColor:'#1f77b4'}
});

// --- Interactive reflection process ---
var clickedPoint = null;
var reflectedPts = [];
var usedPts = new Set();

for (let i=0; i<objPts.length; i++){
    objPts[i].on('down', function(){
        if (usedPts.has(i)) return;
        objPts.forEach((t,j)=> {
            if (!usedPts.has(j)) t.setAttribute({fillColor:'#1f77b4'});
        });
        clickedPoint = objPts[i];
        clickedPoint.setAttribute({fillColor:'red'});
    });
}

board.on('down', function(e){
    if (!clickedPoint) return;

    var cPos = board.getMousePosition(e);
    var coords = new JXG.Coords(JXG.COORDS_SCREEN, cPos, board);
    var xClick = coords.usrCoords[1];
    var yClick = coords.usrCoords[2];

    var idx = objPts.indexOf(clickedPoint);
    var labelPrime = labels[idx] + "'";
    var studPt = board.create('point', [xClick, yClick], {
        size: 3,
        name: labelPrime,
        fillColor: '#ff7f0e',
        label: {offset:[-10,10]}
    });
    reflectedPts.push(studPt);

    usedPts.add(idx);
    clickedPoint.setAttribute({fillColor:'#b0b0b0'});
    clickedPoint = null;

    if (reflectedPts.length === objPts.length){
        board.create('polygon', reflectedPts, {
            fillColor: '#fdd0a2',
            borders: {strokeColor:'#ff7f0e'}
        });
    }
});
[[/jsxgraph]]

feedbackvariables.text:
dist(a, b) := sqrt((first(a)-first(b))^2 + (second(a)-second(b))^2);
is_close(ans, model, tol) := lmax(map(lambda([x,y], dist(x,y)), ans, model)) < tol;

tAns: map(lambda([P], reflect_point(P, m, c)), pts);
